import html,json
from pathlib import Path
P=Path(__file__).resolve().parent;M=P/'media';M.mkdir(exist_ok=True)
E=html.escape
CSS='body{font:18px/1.55 system-ui,sans-serif;max-width:960px;margin:1.5rem auto;padding:0 1rem;color:#17334a;overflow-wrap:anywhere}h1,h2{line-height:1.2}article,section{padding:1rem;border:1px solid #bed5df;border-radius:12px;margin:1rem 0}table{border-collapse:collapse;width:100%;table-layout:fixed}td,th{text-align:left;border:1px solid #adb9c2;padding:.4rem;overflow-wrap:anywhere}input,textarea,button{font:inherit;padding:.6rem}input{width:85%;max-width:40rem}.en{color:#415461}.notice{background:#eef7fb;padding:1rem}.bar{height:1.5rem;background:#168bb0;margin:.25rem 0}nav{display:flex;flex-wrap:wrap;gap:.8rem}a{color:#00598b}small{font-size:1rem}@media print{button,input,label,.search-hint{display:none}body{max-width:none;font-size:16pt}article{break-inside:avoid}.poster{border:2px solid #234}@page{size:A3 landscape;margin:15mm}}'
def save(name,title,body,script=''):
 s='<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+E(title)+'</title><style>'+CSS+'</style></head><body><h1>'+E(title)+'</h1><p class="notice">Eigenes fiktives didaktisches Modellmaterial von SkillPilot, CC-BY-4.0. Keine tatsächliche Studie, Durchführung oder Lernleistung. / Authored fictitious model material; no actual study, delivery or learner performance.</p>'+body+('<script>'+script+'</script>' if script else '')+'</body></html>\n'
 (M/name).write_text(s)
cards=[
 ('D1','Stadtlabor / City laboratory','Stadtbäume Blüte Pollen Bestäuber urban trees flowering pollinator food','12 Baumflächen: blühend40, nichtblühend8 Besuche/Stunde. Keine randomisierte Zuteilung, Artenzahl nicht erfasst. /12tree plots: flowering40, nonflowering8 visits/hour. No random assignment; no species counts.'),
 ('D2','Blütennetz / Flower network','Stadtbäume Blüte Nahrung Bestäuber Wetter urban trees flowers food pollinator weather','Baumblüte → Nahrung; angrenzende Wiese → weitere Nahrung; Wetter → Aktivität. Pfeile sind im Modell mögliche Einflüsse, keine Messgrößen. /Tree flowers→food; adjacent meadow→more food; weather→activity. Arrows are modeled possible influences, not measurements.'),
 ('D3','Anzeige / Advert','Stadtbaum Blüte Bestäuber Arten urban tree flower pollinator species','Unser Baum garantiert fünfmal mehr Arten. Keine Artenzählung oder Ursachenkontrolle. Zweck: Werbung. /Our tree guarantees five times more species. No species count or causal control; promotional purpose.'),
 ('D4','Wetterübersicht / Weather note','Wetter Temperatur weather temperature','Ein kalter Regentag verändert Aktivität; keine Baumarten oder Nahrungsangebote erhoben. /A cold rainy day changes activity; no tree types or food resources measured.'),
 ('D5','Windbestäubung / Wind pollination','Wind Baum Pollen wind tree pollen','Eine im Modell windbestäubte Baumart liefert keinen Nektar. Aussage nur über diese Art, keine allgemeine Baumregel. /A modeled wind-pollinated tree provides no nectar. This species only, no universal tree rule.'),
 ('E1','Keimtabelle / Germination table','Keimung Wasser Sauerstoff Überschwemmung germination water oxygen flooding','Gleiche Temperatur, je20Samen: mäßigfeucht18, trocken2, ständigüberflutet5 gekeimt. /Equal temperature,20seeds each: moderatelymoist18, dry2, continuouslyflooded5 germinated.'),
 ('E2','Keimablauf / Germination flow','Keimung Wasseraufnahme Sauerstoff flooding germination water uptake oxygen','Wasseraufnahme → Stoffwechsel; Sauerstoffzufuhr → aerobe Energiebereitstellung. Beide beeinflussen Keimung im Modell. /Water uptake→metabolism; oxygen supply→aerobic energy provision. Both affect germination in the model.'),
 ('E3','Blogüberschrift / Blog heading','Keimung Licht Sonne germination light sun','Alle Pflanzen brauchen zum Keimen Sonne. Kein Versuch, keine Artangabe. /All plants need sunlight to germinate. No experiment or species stated.'),
 ('E4','Artkarte Lichtkeimer / Light-requiring seed species card','Keimung Lichtkeimer Hell Dunkel Art light germination light dark species','Ergänzung für die frische Recherche: Art L im Modell, gleich feucht/warm, Hell16/20,Dunkel1/20. Daten beziehen sich nur auf L/Modellbedingungen. /Fresh-search addition: modeled speciesL, equallymoist/warm, light16/20,dark1/20. Data apply only to L/model conditions.'),
 ('E5','Düngerkatalog / Fertilizer catalog','Dünger Minerale fertilizer minerals','Mineraldünger liefert Nährstoffe, ist keine Lichtquelle; keine Wasser-/Keimdaten. /Mineral fertilizer provides nutrients, not light; no water/germination data.')]
def spaced(t):
 import re
 t=re.sub(r'(?<=\d)(?=[A-Za-zÄÖÜäöüß])',' ',t);t=re.sub(r'(?<=[A-Za-zÄÖÜäöüß])(?=\d)',' ',t);return re.sub(r'(?<=[,:;])(?=[\w])',' ',t)
catalog='''<p>Offline-Digitalindex: Suchbegriffe eingeben, Treffer vergleichen, Karte öffnen und ID/Passage im eigenen Rechercheprotokoll nennen. Jede Karte hat einen stabilen lokalen Fragment-Lokator. / Offline digital index: enter terms, compare results, open a card and record its ID/passage.</p><label for="query">Suchbegriffe / Search terms</label><input id="query" type="search"><p id="count" role="status"></p><nav>'''+''.join('<a href="#'+c[0]+'">'+c[0]+'</a>' for c in cards)+'</nav>'
for key,title,terms,text in cards:catalog+='<article id="'+key+'" data-terms="'+E((terms+' '+title+' '+text).lower())+'"><h2>'+key+': '+E(title)+'</h2><p>Modellquelle: SkillPilot, '+key+', Absatz1. / Model source: SkillPilot, '+key+', paragraph1.</p><p>'+E(spaced(text))+'</p></article>'
catalog+='<section><h2>Rechercheprotokoll / Research record</h2><p>Notiere auf deinem eigenen Blatt: Frage; Suchbegriffe; analoger Lokator; digitale Karte/Passage; Auswahl; Ausschluss; offene Frage. Hier werden keine Eingaben gespeichert oder übertragen. / Record question, terms, analog locator, digital card/passage, selection, rejection and remaining question on your own sheet. This page stores/transmits no entries.</p></section>'
script="const q=document.getElementById('query');const cards=[...document.querySelectorAll('article[data-terms]')];function search(){const terms=q.value.toLocaleLowerCase().trim().split(/\\s+/).filter(Boolean);let n=0;for(const c of cards){const show=!terms.length||terms.some(t=>c.dataset.terms.includes(t));c.hidden=!show;if(show)n++}document.getElementById('count').textContent=n+' Treffer / results';}q.addEventListener('input',search);search();"
save('research-model-search-index.digital.html','Durchsuchbarer Modellindex / Searchable model index',catalog,script)
analog=[('A1','Stadtbäume / Urban Trees','Kapitel2: Blüten liefern Pollen/Nektar. Kapitel5: Arten besuchen saisonal. /Chapter2: flowers supply pollen/nectar. Chapter5: species visit seasonally.'),('A2','Holzbau / Timber Construction','Kapitel3: Tragfähigkeit von Holz. /Chapter3: timber load bearing.'),('B1','Keimung / Germination','Register Keimung, Seiten4–5: Wasseraufnahme ermöglicht Stoffwechsel. Dauerhafte Überflutung kann Sauerstoffversorgung begrenzen. Register Lichtkeimer, Seite6: artspezifische Hell-Dunkel-Bedingungen müssen geprüft werden. /Germination index,pages4–5: water uptake permits metabolism. Continuous flooding may limit oxygen supply. Light-requiring-seed index,page6: species-specific light/dark conditions require testing.'),('B2','Düngung / Fertilization','Register Düngung, Seite9: Mineraldünger ist keine Lichtquelle. /Fertilization index,page9: mineral fertilizer is not light.')]
body='<p>Ausdrucken und in der gedruckten Fassung Register, Kapitel und Passagen nachschlagen. Dies ist der analoge Teil der eigenen Rechercheübung. / Print this source-card catalog and look up index/chapter/passages on paper.</p><button onclick="window.print()">Drucken / Print</button>'
for key,title,text in analog:body+='<article><h2>'+key+': '+E(title)+'</h2><p>SkillPilot,2026, eigenes Modellmaterial / authored model.</p><p>'+E(spaced(text))+'</p></article>'
save('research-model-source-cards.analog-print.html','Gedruckter Modellkatalog / Printed model catalog',body)

body='<section class="poster"><h2>Blühflächen und Besuche / Flowering plots and visits</h2><p>Gleiche Beobachtungsdauer:30min / Same observation:30min</p><table><thead><tr><th>Modellfläche / Model plot</th><th>Besuche/30min / Visits/30min</th><th>Einheitlich skaliert / Equal scale</th></tr></thead><tbody>'
for label,n in [('Blüte1 / Flowers1',12),('Blüte2 / Flowers2',15),('Blüte3 / Flowers3',13),('Rasen1 / Lawn1',4),('Rasen2 / Lawn2',5),('Rasen3 / Lawn3',3)]:body+='<tr><td>'+E(spaced(label))+'</td><td>'+str(n)+'</td><td><div class="bar" style="width:'+str(n*5)+'%" aria-label="'+str(n)+' visits per30minutes"></div></td></tr>'
body+='</tbody></table><p><strong>Modellbefund: mehr Besuche auf Blühflächen. / Model observation: more visits on flowering plots.</strong></p><p>Blühflächen waren sonniger; Arten wurden nicht gezählt. Kein isolierter Kausaleffekt und kein Artenvielfaltsnachweis. / Flower plots were sunnier; species were not counted. No isolated causal effect or biodiversity proof.</p><p>Quelle: SkillPilot, fiktives Klassendatenset,2026, Tabelle1. / Source: authored fictitious class dataset,table1.</p></section>'
body+='<section><h2>Sprechertext / Delivery text</h2><p>An den Modellblühflächen beobachteten wir12,15,13 Besuche in30min, an den Rasenflächen4,5,3. Das ist eine Beobachtung, keine gezählte Artenvielfalt; Sonnigkeit war verschieden. / Modeled flowering plots had12,15,13 visits in30min and lawn plots4,5,3. These are observations, not species counts; sunshine differed.</p><p>Alternativbeschreibung: sechs Werte mit gemeinsamer Zeitskala, drei größere Blühflächenwerte und drei kleinere Rasenwerte; siehe Zahlen, nicht nur Farben. / Alternative description: six values on a common time scale, three higher flower-plot values and three lower lawn values; use numbers, not color alone.</p></section>'
save('pollinator-results.presentation-digital.html','Folie: Modellbeobachtung / Slide: modeled observation',body)
save('pollinator-results.poster-analog-print.html','Poster: Modellbeobachtung / Poster: modeled observation','<button onclick="window.print()">A3 drucken / A3 print</button>'+body)

resp='<section class="poster"><h2>Vereinfachtes Zellatmungsmodell / Simplified cell respiration model</h2><p><strong>Glucose + Sauerstoff → Kohlenstoffdioxid + Wasser</strong></p><p class="en"><strong>Glucose + oxygen → carbon dioxide + water</strong></p><p>Stoffumsatz / Material conversion: Eingänge links, Ausgänge rechts. / Inputs left, outputs right.</p><p>Chemische Energie wird für Lebensprozesse nutzbar; ein Teil wird als Wärme abgegeben. / Chemical energy becomes usable for life processes; part is released as heat.</p><p>Pflanzen und Tiere können aerobe Zellatmung auch im Licht betreiben. / Plants and animals can carry out aerobic respiration in light too.</p><p>Vereinfachtes Gesamtmodell, keine ATP-Bilanz oder Darstellung aller Teilschritte. / Simplified overall model, no ATP accounting or all intermediate steps.</p><p>Quelle: SkillPilot,2026, eigenes Zellatmungsmodell, Abschnitt1. / Source: authored respiration model,section1.</p></section><section><h2>Sprechertext / Delivery</h2><p>Sauerstoff ist ein Stoff der Reaktion, keine neu erzeugte Energie. Die Energie stammt aus chemischen Umsetzungen. Pflanzen sind nicht auf nächtliche Zellatmung beschränkt. / Oxygen is a reactant, not newly created energy. Energy comes from chemical conversions. Plants do not respire only at night.</p><p>Alternativbeschreibung: Wortgleichung mit Glucose und Sauerstoff als Eingang, Kohlenstoffdioxid und Wasser als Ausgang; getrennte Energie-/Wärmeaussage, kein ATP-Zahlenmodell. / Alternative description: word equation with glucose/oxygen inputs, carbon dioxide/water outputs; separate energy/heat claim and no ATP numerical model.</p></section>'
save('respiration-model.presentation-digital.html','Digitale Kurszusammenfassung / Digital course summary',resp)
save('respiration-model.station-analog-print.html','Analoge Lernstation / Analog learning station','<button onclick="window.print()">Drucken / Print</button>'+resp)

citation='<article id="C1"><h2>C1: Modellbericht Keimung / Model Germination Report</h2><p>Originalcredits: SkillPilot,2026; eigene CC-BY-4.0. Interne Autorenrolle SchulteamAlpha ist fiktiv. / Original creator: SkillPilot; internal author role SchoolTeamAlpha is fictitious.</p><h3>Abschnitt2 / Section2</h3><blockquote>Im Modell keimten18von20Samen bisTag6.</blockquote><blockquote lang="en">In the model18of20seeds germinated byday6.</blockquote><table><caption>Tabelle1 / Table1</caption><tr><th>Samen / Seeds</th><th>Tag / Day</th><th>Gekeimt / Germinated</th></tr><tr><td>20</td><td>6</td><td>18</td></tr></table></article><article id="C2"><h2>C2: Modell Nährstoffvergleich / Model Nutrient Comparison</h2><p>SkillPilot,2026; eigene CC-BY-4.0, Abschnitt3 / Section3.</p><table><caption>Tabelle2 / Table2</caption><tr><th>Standort / Location</th><th>Nitrat mg/L / Nitrate mg/L</th></tr><tr><td>A</td><td>2</td></tr><tr><td>B</td><td>8</td></tr></table><h3>Figur1 / Figure1</h3><p>A:2mg/L</p><div class="bar" style="width:20%"></div><p>B:8mg/L</p><div class="bar" style="width:80%"></div></article><article id="C3"><h2>C3: Modellübersicht / Model Overview</h2><p>SkillPilot,2026, Abschnitt1 / Section1.</p><p>Einzelmessungen beweisen keine Ursache. / Single measurements do not prove causation.</p></article>'
save('citation-original-model-cards.html','Originale Modellquellen / Original model sources',spaced(citation))
